package studio.jiayu.neoagent;
import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.view.accessibility.AccessibilityWindowInfo;import android.widget.*;

/** Orange control surface. Owns presentation and position only, never task or model decisions. */
final class ControlBar {
 private final ControlService host;private WindowManager windows;
 ControlCapsule view;TextView detail;private String windowTitle="";private long dragEpoch,avoidingEpoch=-1;
 ControlBar(ControlService host){this.host=host;}
 private int dp(int n){return host.dp(n);}
 private int clamp(int value,int min,int max){return Math.max(min,Math.min(Math.max(min,max),value));}
 boolean owns(AccessibilityWindowInfo w){return w.getType()==AccessibilityWindowInfo.TYPE_ACCESSIBILITY_OVERLAY&&!windowTitle.isEmpty()&&windowTitle.contentEquals(w.getTitle()==null?"":w.getTitle());}
 Rect bounds(){if(view==null||!view.isAttachedToWindow())return null;for(AccessibilityWindowInfo w:host.getWindows())if(w.getType()==AccessibilityWindowInfo.TYPE_ACCESSIBILITY_OVERLAY&&windowTitle.contentEquals(w.getTitle()==null?"":w.getTitle())){Rect r=new Rect();w.getBoundsInScreen(r);if(!r.isEmpty())return r;}return null;}
 void show(boolean human,String status,Runnable takeover,Runnable resume,Runnable stop){
  hide();windows=(WindowManager)host.getSystemService(Context.WINDOW_SERVICE);final int[] origin=new int[6],wanted=new int[2];final boolean[] ready={false};
  view=new ControlCapsule(host,new ControlCapsule.Drag(){
   public void begin(){dragEpoch++;ready[0]=false;Rect b=bounds();if(b==null)return;WindowManager.LayoutParams p=(WindowManager.LayoutParams)view.getLayoutParams();origin[0]=wanted[0]=b.left;origin[1]=wanted[1]=b.top;origin[2]=p.x;origin[3]=p.y;origin[4]=b.width();origin[5]=b.height();ready[0]=true;}
   public void move(float dx,float dy){if(!ready[0]||view==null)return;android.util.DisplayMetrics m=host.screenMetrics();wanted[0]=clamp(origin[0]+(int)dx,dp(7),m.widthPixels-origin[4]-dp(7));wanted[1]=clamp(origin[1]+(int)dy,dp(28),m.heightPixels-origin[5]-dp(38));WindowManager.LayoutParams p=(WindowManager.LayoutParams)view.getLayoutParams();p.x=origin[2]+wanted[0]-origin[0];p.y=origin[3]+wanted[1]-origin[1];windows.updateViewLayout(view,p);}
   public void end(){if(!ready[0])return;android.util.DisplayMetrics m=host.screenMetrics();float x=(wanted[0]-dp(7))/(float)Math.max(1,m.widthPixels-origin[4]-dp(14)),y=(wanted[1]-dp(28))/(float)Math.max(1,m.heightPixels-origin[5]-dp(66));host.getSharedPreferences("ui",0).edit().putFloat("controlBarX",Math.max(0,Math.min(1,x))).putFloat("controlBarY",Math.max(0,Math.min(1,y))).apply();}
  });
  view.setGravity(Gravity.CENTER_VERTICAL);view.setPadding(dp(11),dp(7),dp(7),dp(7));GradientDrawable bg=new GradientDrawable();bg.setColor(0xF22B2928);bg.setCornerRadius(dp(22));bg.setStroke(dp(1),0xFFED976F);view.setBackground(bg);view.setElevation(dp(8));
  LinearLayout labels=new LinearLayout(host);labels.setOrientation(LinearLayout.VERTICAL);TextView title=new TextView(host);title.setText(human?"● 你正在接管":"● Agent 正在控制");title.setTextColor(human?0xFFE8C4B1:0xFFFFAB85);title.setTextSize(12);title.setTypeface(null,android.graphics.Typeface.BOLD);title.setSingleLine();labels.addView(title);
  detail=new TextView(host);detail.setTextColor(Color.WHITE);detail.setTextSize(10);detail.setSingleLine();detail.setEllipsize(android.text.TextUtils.TruncateAt.END);detail.setText(status);labels.addView(detail);int width=Math.max(90,Math.min(150,(int)(host.screenMetrics().widthPixels/host.screenMetrics().density)-190));view.addView(labels,new LinearLayout.LayoutParams(dp(width),-2));
  view.addView(button(human?"交还 Agent":"接管",human?82:54,0xFFFFAB85,human?resume:takeover));view.addView(button("结束",44,0xFF54423A,stop));
  view.measure(View.MeasureSpec.makeMeasureSpec(host.screenMetrics().widthPixels,View.MeasureSpec.AT_MOST),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));WindowManager.LayoutParams p=new WindowManager.LayoutParams(-2,-2,WindowManager.LayoutParams.TYPE_ACCESSIBILITY_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|(human?0:WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON),PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.LEFT;windowTitle="Neo control "+java.util.UUID.randomUUID();p.setTitle(windowTitle);p.x=Math.max(dp(7),host.screenMetrics().widthPixels-view.getMeasuredWidth()-dp(7));p.y=Math.max(dp(28),(host.screenMetrics().heightPixels-view.getMeasuredHeight())/2);windows.addView(view,p);
  final ControlCapsule shown=view;final long epoch=dragEpoch;view.postDelayed(()->{if(view==shown&&dragEpoch==epoch)restore();},250);
 }
 private Button button(String text,int width,int color,Runnable action){Button b=new Button(host);b.setText(text);b.setAllCaps(false);b.setTextSize(12);b.setTextColor(color==0xFFFFAB85?0xFF25130B:0xFFFFE4D7);b.setMinWidth(0);b.setMinimumWidth(0);b.setMinHeight(0);b.setMinimumHeight(0);b.setPadding(dp(3),0,dp(3),0);b.setStateListAnimator(null);GradientDrawable bg=new GradientDrawable();bg.setColor(color);bg.setCornerRadius(dp(13));b.setBackground(bg);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(width),dp(38));p.leftMargin=dp(6);b.setLayoutParams(p);b.setOnClickListener(v->action.run());return b;}
 void update(String status){if(detail!=null)detail.setText(status);}
 void restore(){Rect b=bounds();if(b==null||view==null)return;android.util.DisplayMetrics m=host.screenMetrics();SharedPreferences prefs=host.getSharedPreferences("ui",0);int minX=dp(7),minY=dp(28),maxX=Math.max(minX,m.widthPixels-b.width()-dp(7)),maxY=Math.max(minY,m.heightPixels-b.height()-dp(38));int x=minX+(int)((maxX-minX)*prefs.getFloat("controlBarX",1f)),y=prefs.contains("controlBarY")?minY+(int)((maxY-minY)*prefs.getFloat("controlBarY",.5f)):clamp((m.heightPixels-b.height())/2,minY,maxY);WindowManager.LayoutParams p=(WindowManager.LayoutParams)view.getLayoutParams();p.x+=x-b.left;p.y+=y-b.top;windows.updateViewLayout(view,p);}
 boolean avoid(Rect path)throws Exception{if(view==null)return false;Rect b=bounds();if(b==null)throw new Exception("控制条边界正在同步");if(!Rect.intersects(b,path))return false;android.util.DisplayMetrics m=host.screenMetrics();int y=b.centerY()<m.heightPixels/2?m.heightPixels-b.height()-dp(38):dp(28);Rect next=new Rect(b.left,y,b.right,y+b.height());if(Rect.intersects(next,path))throw new Exception("控制条暂时遮挡动作路径");avoidingEpoch=dragEpoch;WindowManager.LayoutParams p=(WindowManager.LayoutParams)view.getLayoutParams();p.y+=y-b.top;windows.updateViewLayout(view,p);return true;}
 void restoreAfterAvoidance(){if(avoidingEpoch==dragEpoch)restore();avoidingEpoch=-1;}
 void hide(){if(view!=null)try{windows.removeView(view);}catch(Exception ignored){}view=null;detail=null;avoidingEpoch=-1;}
}
